package br.com.marquesautodetail.api.horario; import br.com.marquesautodetail.api.empresa.Empresa; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="horarios_disponiveis") public class HorarioDisponivel{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Enumerated(EnumType.STRING) private DayOfWeek diaSemana; private LocalTime horaInicio; private LocalTime horaFim; private Boolean ativo=true; @ManyToOne private Empresa empresa; public Long getId(){return id;} public void setId(Long id){this.id=id;} public DayOfWeek getDiaSemana(){return diaSemana;} public void setDiaSemana(DayOfWeek diaSemana){this.diaSemana=diaSemana;} public LocalTime getHoraInicio(){return horaInicio;} public void setHoraInicio(LocalTime horaInicio){this.horaInicio=horaInicio;} public LocalTime getHoraFim(){return horaFim;} public void setHoraFim(LocalTime horaFim){this.horaFim=horaFim;} public Boolean getAtivo(){return ativo;} public void setAtivo(Boolean ativo){this.ativo=ativo;} public Empresa getEmpresa(){return empresa;} public void setEmpresa(Empresa empresa){this.empresa=empresa;} }
